import string

def get_valid_input(prompt):
    """Get a valid input from the user."""
    while True:
        user_input = input(prompt).strip().lower()
        if len(user_input) == 1 and user_input in string.ascii_lowercase:
            return user_input
        else:
            print("Please enter a single lowercase letter.")

def play_hangman():
    """Play a game of Hangman."""
    # Define the word to guess
    word = "example"
    num_guesses = len(word)

    # Initialize the game board
    guessed_letters = []
    game_board = [f"_" * num_guesses for _ in range(num_guesses)]

    print("Welcome to Hangman!")
    print(f"You have {num_guesses} guesses to guess the word.")

    while "_" in game_board:
        # Get user input
        letter = get_valid_input("Guess a letter: ")

        # Check if the letter is in the word
        if letter in word:
            for i, char in enumerate(word):
                if char == letter:
                    game_board[i] = char
        else:
            num_guesses -= 1

        # Print the game board
        print(f"\n".join(game_board))

        # Check if the user has won
        if "_" not in game_board:
            print("Congratulations! You guessed the word correctly.")
            break

        # Check if the user has lost
        if num_guesses == 0:
            print("Sorry, you ran out of guesses. The word was 'example'.")
            break

    play_again = input("Do you want to play again? (yes/no): ").lower()
    if play_again == "yes":
        play_hangman()
    else:
        print("Thanks for playing!")

if __name__ == "__main__":
    play_hangman()
```

